var n=`0192-cannoli-siciliani`;var t=`world-0192`;var s=`IT`;var a=`southern-europe`;var o=8;var r=65;var g={en:`Cannoli Siciliani`,ua:`Сицилійські канолі`};var l={en:`A classic dish from Italy, featuring chicken egg, ricotta, pistachio. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Італія. Основні складники: куряче яйце, рикота, фісташка. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 25 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 25 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:25,i:[[`all-purpose-flour`,380,`g`],[`white-granulated-sugar`,35,`g`],[`unsalted-butter`,55,`g`],[`chicken-egg`,1,`pcs`],[`dry-white-wine`,100,`ml`],[`table-salt`,2,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:17,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 12 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 12 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:12,i:[[`sunflower-oil`,700,`ml`]]},{en:`Whisk or whip the listed ingredients to a smooth, light consistency, then keep cool until needed.`,ua:`Збийте зазначені складники до гладкої легкої консистенції, після чого зберігайте в прохолоді до використання.`,t:[`whipping`],m:7,i:[[`ricotta`,550,`g`],[`powdered-sugar`,145,`g`],[`dark-chocolate`,100,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`pistachio`,85,`g`]]}];var h={slug:n,id:t,country:`IT`,region:a,servings:8,minutes:65,title:g,text:l,steps:d};export{s as country,h as default,t as id,r as minutes,a as region,o as servings,n as slug,d as steps,l as text,g as title};